package com.marketplace.productservice;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Version Long version; @Column(nullable=false) String name; @Column(nullable=false,precision=19,scale=2) BigDecimal price; @Column(nullable=false) int stock; protected Product(){} Product(String n,BigDecimal p,int s){name=n;price=p;stock=s;} public Long getId(){return id;} public String getName(){return name;} public BigDecimal getPrice(){return price;} public int getStock(){return stock;} public boolean isAvailable(){return stock>0;} void update(String n,BigDecimal p,int s){name=n;price=p;stock=s;} void reserve(int quantity){if(quantity<=0||stock<quantity)throw new InsufficientStockException(id,stock);stock-=quantity;} }
